/// <summary>
/// Base class for PricingAttribute table <c>EcoResProductCategory</c>
/// </summary>
internal abstract class GUPPricingAttributeEcoResProductCategory extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
protected EcoResProductCategory getTableRecord(Common _pricingObject)
{
    EcoResProductCategory ecoResProductCategory;
    SalesLine salesLine = _pricingObject as SalesLine;

    if (salesLine.ItemId)
    {
        ecoResProductCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(
                                                                    salesLine.ItemId,
                                                                    EcoResCategoryNamedHierarchyRole::Sales);
    }

    return ecoResProductCategory;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;
    QueryBuildDataSource qbdsExistsJoin;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(EcoResProductCategory));
        qbds.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProductCategory, Product));
        qbds.joinMode(JoinMode::InnerJoin);

        qbds = qbds.addDataSource(tableNum(EcoResCategory));
        qbds.addLink(fieldNum(EcoResProductCategory, Category), fieldNum(EcoResCategory, RecId));
        qbds.joinMode(JoinMode::InnerJoin);

        qbdsExistsJoin = qbds.addDataSource(tableNum(EcoResCategoryHierarchyRole));
        qbdsExistsJoin.addLink(fieldNum(EcoResProductCategory, CategoryHierarchy), fieldNum(EcoResCategoryHierarchyRole, CategoryHierarchy));
        qbdsExistsJoin.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
